import db

_mem = {}

def lookup(key):
    """缓存优先；未命中回源 db.fetch 并写入缓存。"""
    if key in _mem:
        return _mem[key]
    value = db.fetch(key)
    if value is not None:
        _mem[key] = value
    return value


def put(key, value):
    _mem[key] = value


def mem_size():
    return len(_mem)
